"use client";
import { addChamadaReplacement, removeChamadaReplacement, chamadaSaveMatches } from "@/lib/kids/chamada-replacement";
import { kidsStudentHistory } from "../../lib/kids/student-history";

import { useEffect, useMemo, useRef, useState } from "react";
import styles from "./KidsPage.module.css";
import { KidsReplacementOperationSummary, KidsStudentReplacementBalance } from "./KidsReplacementBalance";
import { computeKidsClassReplacementBalance, computeKidsStudentReplacementBalance, isKidsFifthMonthlyLesson, kidsBalanceSigned, type KidsReplacementBalance } from "@/lib/kids/replacement-balance";
import {
  createKidsSeed,
  kidsClassName,
  normalizeKidsData,
} from "@/lib/kids/seed";
import type {
  KidsAttendanceStatus,
  KidsCategory,
  KidsClass,
  KidsData,
  KidsEvent,
  KidsLesson,
  KidsReplacement,
  KidsStudent,
} from "@/types/kids";
import type { FinanceData } from "@/types/financeiro";
import { reconcileKidsFinance } from "@/lib/financeiro/kids-sync";
import {
  KIDS_REPLACEMENT_INTEGRITY_VERSION,
  recordCompletedReplacement,
  replacementRosterIsValid,
} from "@/lib/kids/replacement-integrity";

type KidsTab = "dashboard" | "agenda" | "classes" | "students" | "replacements" | "events" | "reports";
type AgendaFilter = "ALL" | "COMPLETED" | "CANCELLED";
export type KidsLessonOpenRequest={date:string;time:string;category:KidsCategory;lessonId?:string};
const categoryLabel: Record<KidsCategory, string> = {
  RED: "Vermelha",
  ORANGE: "Laranja",
  GREEN: "Verde",
  YELLOW: "Amarela",
};
const weekdayLabel = [
  "domingo",
  "segunda",
  "terça",
  "quarta",
  "quinta",
  "sexta",
  "sábado",
];
const statusLabel = {
  SCHEDULED: "Agendada",
  COMPLETED: "Realizada",
  CANCELLED: "Cancelada",
  HOLIDAY: "Feriado",
};
const localeCompare = (a: string, b: string) => a.localeCompare(b, "pt-BR");
const formatDate = (value: string) =>
  new Date(`${value}T12:00:00`).toLocaleDateString("pt-BR");
const currentMonth = () => new Date().toISOString().slice(0, 7);
function cancelReasonText(lesson:KidsLesson){
  if(lesson.cancelReason==="RAIN")return "Chuva";
  if(lesson.cancelReason==="OTHER")return lesson.cancelReasonOther?.trim()||"Outros";
  return "";
}
function calendarLocalSlot(value:string){
  const date=new Date(value);
  const parts=new Intl.DateTimeFormat("sv-SE",{timeZone:"America/Sao_Paulo",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",hour12:false}).formatToParts(date);
  const read=(type:string)=>parts.find(part=>part.type===type)?.value||"";
  return {date:`${read("year")}-${read("month")}-${read("day")}`,time:`${read("hour")}:${read("minute")}`};
}
const groupName=(classes:KidsClass[],id:string)=>classes.find(group=>group.id===id)?.name||"Turma";
const normalizeName=(value:string)=>value.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]/g,"");
function whatsappNumber(phone?:string){
  const digits=(phone||"").replace(/\D/g,"");
  if(!digits)return {href:"",missingDdd:false};
  if(digits.length===8||digits.length===9)return {href:"",missingDdd:true};
  if((digits.length===12||digits.length===13)&&digits.startsWith("55"))return {href:`https://wa.me/${digits}`,missingDdd:false};
  if(digits.length===10||digits.length===11)return {href:`https://wa.me/55${digits}`,missingDdd:false};
  return {href:"",missingDdd:false};
}

export default function KidsPage({ onBack, openRequest, openStudentId }: { onBack: () => void; openRequest?:KidsLessonOpenRequest|null; openStudentId?:string|null }) {
  const [data, setData] = useState<KidsData | null>(null);
  const [tab, setTab] = useState<KidsTab>("dashboard");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [notice, setNotice] = useState("");
  const [month, setMonth] = useState(currentMonth());
  const [lessonId, setLessonId] = useState<string | null>(null);
  const [classId, setClassId] = useState<string | null>(null);
  const [studentId, setStudentId] = useState<string | null>(null);
  const [reportKind, setReportKind] = useState<"student" | "class" | "financial">("student");
  const [reportId, setReportId] = useState("");
  const [financeData,setFinanceData]=useState<FinanceData|null>(null);
  const [agendaFilter, setAgendaFilter] = useState<AgendaFilter>("ALL");
  const [vacanciesOnly, setVacanciesOnly] = useState(false);
  const [showReplacementForm,setShowReplacementForm]=useState(false);
  const [showInactiveStudents,setShowInactiveStudents]=useState(false);
  const [showNewStudentForm,setShowNewStudentForm]=useState(false);
  const [studentSearch,setStudentSearch]=useState("");
  const [dashboardStudentSearch,setDashboardStudentSearch]=useState("");
  const [replacementSearch,setReplacementSearch]=useState("");
  const kidsHistoryReady=useRef(false);
  const kidsBackRestoring=useRef(false);

  useEffect(()=>{
    const snapshot={...window.history.state,dmpKids:true,dmpKidsMonth:month,dmpKidsAgendaFilter:agendaFilter,dmpKidsTab:tab,dmpKidsLessonId:lessonId,dmpKidsClassId:classId,dmpKidsStudentId:studentId};
    if(!kidsHistoryReady.current){
      const saved=window.history.state;
      if(saved?.view==="kids"&&saved?.dmpKids&&["dashboard","agenda","classes","students","replacements","events","reports"].includes(saved.dmpKidsTab)){
        setTab(saved.dmpKidsTab);setLessonId(saved.dmpKidsLessonId||null);setClassId(saved.dmpKidsClassId||null);setStudentId(saved.dmpKidsStudentId||null);
        if(/^\d{4}-\d{2}$/.test(saved.dmpKidsMonth||""))setMonth(saved.dmpKidsMonth);
        if(["ALL","COMPLETED","CANCELLED"].includes(saved.dmpKidsAgendaFilter))setAgendaFilter(saved.dmpKidsAgendaFilter);
        kidsBackRestoring.current=true;
      }else window.history.replaceState(snapshot,"",window.location.href);
      kidsHistoryReady.current=true;
      return;
    }
    if(kidsBackRestoring.current){kidsBackRestoring.current=false;return;}
    const state=window.history.state;
    const same=state?.dmpKids&&state.dmpKidsTab===tab&&(state.dmpKidsLessonId||null)===(lessonId||null)&&(state.dmpKidsClassId||null)===(classId||null)&&(state.dmpKidsStudentId||null)===(studentId||null);
    if(!same)window.history.pushState(snapshot,"",window.location.href);
    else window.history.replaceState(snapshot,"",window.location.href);
  },[tab,lessonId,classId,studentId,month,agendaFilter]);

  useEffect(()=>{
    const onPopState=(event:PopStateEvent)=>{
      const state=event.state;
      if(!state?.dmpKids)return;
      kidsBackRestoring.current=true;
      setTab((state.dmpKidsTab||"dashboard") as KidsTab);
      setLessonId(state.dmpKidsLessonId||null);
      setClassId(state.dmpKidsClassId||null);
      setStudentId(state.dmpKidsStudentId||null);
      if(/^\d{4}-\d{2}$/.test(state.dmpKidsMonth||""))setMonth(state.dmpKidsMonth);
      if(["ALL","COMPLETED","CANCELLED"].includes(state.dmpKidsAgendaFilter))setAgendaFilter(state.dmpKidsAgendaFilter);
    };
    window.addEventListener("popstate",onPopState);
    return()=>window.removeEventListener("popstate",onPopState);
  },[]);

  useEffect(() => {
    void load();
  }, []);
  useEffect(()=>{
    if(!data||!openRequest)return;
    const target=data.lessons.find(lesson=>{
      if(openRequest.lessonId)return lesson.id===openRequest.lessonId;
      const lessonClass=data.classes.find(group=>group.id===lesson.classId);
      const category=lesson.replacementCategory||lessonClass?.category;
      const time=lesson.replacementStartTime||lessonClass?.startTime;
      return lesson.date===openRequest.date&&category===openRequest.category&&time===openRequest.time;
    });
