  async function load() {
    setLoading(true);
    try {
      const response = await fetch("/api/kids", { cache: "no-store" });
      const payload = await response.json();
      if (!response.ok) throw new Error(payload.error);

      if(payload.updatedAt){
        window.sessionStorage.setItem(
          "dmp_kids_cloud_updated_at",
          String(payload.updatedAt)
        );
      }else{
        window.sessionStorage.removeItem(
          "dmp_kids_cloud_updated_at"
        );
      }
      let next = normalizeKidsData(payload.data || createKidsSeed());
      try {
        const financeResponse = await fetch("/api/finance", {
          cache: "no-store",
        });
        if (financeResponse.ok) {
          const financePayload = await financeResponse.json();
          if (financePayload.data){
            const reconciled=reconcileKidsFinance(financePayload.data as FinanceData,next);
            setFinanceData(reconciled.data);
            next=mergeFinanceProfiles(next,reconciled.data);
            if(reconciled.changed){
              await createFinanceSafetyBackup();
              const financeHeaders:Record<string,string>={
                "Content-Type":"application/json"
              };

              if(financePayload.updatedAt){
                financeHeaders["X-DMP-Expected-Updated-At"]=
                  String(financePayload.updatedAt);
              }

              const save=await fetch("/api/finance",{
                method:"PUT",
                headers:financeHeaders,
                body:JSON.stringify(reconciled.data)
              });
              if(!save.ok)throw new Error("Falha ao salvar reconciliação Kids.");
            }
          }
        }
      } catch (error) {
        console.error(
          "Kids: falha na reconciliação financeira.",
          error
        );

        setNotice(
          "Os dados Kids foram carregados, mas a sincronização com o Financeiro não pôde ser concluída. Atualize a página antes de fazer alterações financeiras."
        );
      }

      setData(next);
      if (
        !payload.data ||
        JSON.stringify(next) !== JSON.stringify(payload.data)
      )
        await persist(next, "Dados das aulas atualizados.");
    } catch {
      setNotice("Não foi possível carregar o Tênis Kids.");
    } finally {
      setLoading(false);
    }
  }
  async function persist(next: KidsData, message = "Alterações salvas.", confirmation?:KidsLesson) {
    const stamped = { ...next, updatedAt: new Date().toISOString() };
    setData(stamped);
    setSaving(true);
    try {
      const expected =
        window.sessionStorage.getItem(
          "dmp_kids_cloud_updated_at"
        ) || "";

      const headers: Record<string,string> = {
        "Content-Type": "application/json",
      };

      if(expected){
        headers["X-DMP-Expected-Updated-At"] = expected;
      }

      const response = await fetch("/api/kids", {
        method: "PUT",
        headers,
        body: JSON.stringify(stamped),
      });

      const saved = await response.json().catch(() => ({}));

      if(response.status === 409){
        setData(data);
        setNotice(
          "As Aulas Kids foram alteradas em outra aba ou dispositivo. Atualize a página antes de continuar."
        );
        return false;
      }

      if (!response.ok) { setData(data); setNotice(saved.error || "Erro ao salvar. Tente novamente."); return false; }

      if(saved.updatedAt){
        window.sessionStorage.setItem(
          "dmp_kids_cloud_updated_at",
          String(saved.updatedAt)
        );
      }
      if(saved.data) setData(saved.data);
      setNotice(message);
      return true;
    } catch {
      if(confirmation){
        try{
          const check=await fetch("/api/kids",{cache:"no-store"});
          const confirmed=await check.json();
          if(check.ok&&confirmed.data&&confirmed.updatedAt&&chamadaSaveMatches(confirmation,confirmed.data.lessons?.find((item:KidsLesson)=>item.id===confirmation.id))){
            window.sessionStorage.setItem("dmp_kids_cloud_updated_at",String(confirmed.updatedAt));setData(confirmed.data);setNotice(message);return true;
          }
        }catch{}
      }
      setData(data);
      setNotice(confirmation?"A confirmação da gravação não foi obtida. Atualize a página e confira a chamada antes de repetir.":"Erro ao salvar. Tente novamente.");
      return false;
    } finally {
      setSaving(false);
    }
  }
  async function syncStudentFinance(student:KidsStudent,studentClasses:KidsClass[]){
    try{
      const response=await fetch("/api/finance",{cache:"no-store"});
      if(!response.ok)throw new Error();
      const payload=await response.json();
      const finance=payload.data as FinanceData|undefined;
      if(!finance||!data)throw new Error();
      const reconciled=reconcileKidsFinance(
         finance,
         {...data,classes:studentClasses},
         {createMissing:true,updateFromProfile:true,onlyStudentId:student.id},
       );
      setFinanceData(reconciled.data);
      if(reconciled.changed){
        await createFinanceSafetyBackup();
        const financeHeaders:Record<string,string>={
          "Content-Type":"application/json"
        };

        if(payload.updatedAt){
          financeHeaders["X-DMP-Expected-Updated-At"]=
            String(payload.updatedAt);
        }

        const save=await fetch("/api/finance",{
          method:"PUT",
          headers:financeHeaders,
          body:JSON.stringify(reconciled.data)
        });
        if(!save.ok)throw new Error();
      }
      void student;
    }catch{
      setNotice("Cadastro salvo na DS, mas o Financeiro não atualizou. Tente salvar a criança novamente.");
    }
  }
