  const semesterCompleted=semesterLessons.filter(item=>item.status==="COMPLETED"||(item.status==="SCHEDULED"&&lessonHasPassed(item,classes))).length;
  const semesterCancelled=semesterLessons.filter(item=>item.status==="CANCELLED").length;
  const semesterScheduled=semesterLessons.length;
  const totalVacancies=Math.max(0,capacity-occupied);
  const occupancy=capacity?Math.round((occupied/capacity)*100):0;
  const activeClassesByCapacity=classes.filter(item=>item.active).map(item=>{
    const classCapacity=item.category==="RED"||item.category==="ORANGE"?6:4;
    const enrolled=item.students.filter(student=>student.active).length;
    const rate=classCapacity?Math.round((enrolled/classCapacity)*100):0;
    const status=enrolled>classCapacity?"Acima da capacidade":enrolled===classCapacity?"No limite da capacidade":"Vagas disponíveis";
    return {...item,classCapacity,enrolled,rate,status,vacancies:Math.max(0,classCapacity-enrolled)};
  }).sort((a,b)=>b.rate-a.rate||a.weekday-b.weekday||a.startTime.localeCompare(b.startTime));
  const replacementQuery=normalizeName(replacementSearch);
  const waitingReplacementStudents=replacementStudentRows.filter(item=>item.saldoARepor>0&&(!replacementQuery||normalizeName(item.name).includes(replacementQuery)));
  const advanceReplacementStudents=replacementStudentRows.filter(item=>item.saldoARepor<0&&(!replacementQuery||normalizeName(item.name).includes(replacementQuery)));
  const visibleUpcomingReplacements=upcomingReplacementLessons.filter(lesson=>!replacementQuery||replacementLessonSearchText(lesson).includes(replacementQuery));
  const visibleReplacementHistory=replacementHistoryLessons.filter(lesson=>!replacementQuery||replacementLessonSearchText(lesson).includes(replacementQuery));

  return (
    <div className={styles.page}>
      <header className={styles.hero}>
        <div>
          <button className={styles.back} onClick={onBack}>
            ← Voltar ao DMP
          </button>
          <p>CT DS TENNIS · GESTÃO PEDAGÓGICA</p>
          <h1>Aulas Kids</h1>
          <span>
            Semestre de {formatDate(data.semesterStart)} a{" "}
            {formatDate(data.semesterEnd)}
          </span>
        </div>
        <img src="/logo-ctds.png" alt="CT DS Tennis" />
      </header>
      <nav className={styles.tabs}>
        {(
          [
            ["dashboard", "Visão geral"],
            ["agenda", "Agenda"],
            ["classes", "Turmas"],
            ["students", "Alunos"],
            ["replacements", "Reposições"],
            ["events", "Eventos"],
            ["reports", "Relatórios"],
          ] as [KidsTab, string][]
        ).map(([value, label]) => (
          <button
            key={value}
            className={tab === value ? styles.active : ""}
            onClick={() => setTab(value)}
          >
            {label}
          </button>
        ))}
      </nav>
      {notice ? (
        <div className={styles.notice}>
          {notice}
          <button onClick={() => setNotice("")}>×</button>
        </div>
      ) : null}
      {saving ? <div className={styles.saving}>Salvando...</div> : null}

      {tab === "dashboard" ? (
        <>
          <section className={styles.semesterPanel}>
            <div className={styles.semesterHead}>
              <div>
                <span>COORDENAÇÃO KIDS</span>
                <h2>Painel do semestre</h2>
                <p>{formatDate(data.semesterStart)} a {formatDate(data.semesterEnd)} · visão rápida da operação Kids</p>
              </div>
              <button onClick={() => openAgenda("ALL")}>Abrir agenda do semestre</button>
            </div>
            <div className={styles.semesterStats}>
              <button onClick={() => setTab("students")}><small>Alunos ativos</small><strong>{allKids.length}</strong><span>cadastros ativos</span></button>
              <button onClick={() => {setVacanciesOnly(false);setTab("classes");}}><small>Turmas ativas</small><strong>{classes.filter(item=>item.active).length}</strong><span>{occupied}/{capacity} vagas ocupadas</span></button>
              <button onClick={() => openAgenda("COMPLETED")}><small>Aulas realizadas</small><strong>{semesterCompleted}</strong><span>de {semesterScheduled} previstas</span></button>
              <button onClick={() => openAgenda("CANCELLED")}><small>Aulas canceladas</small><strong>{semesterCancelled}</strong><span>feriados não entram</span></button>
              <button onClick={() => {setVacanciesOnly(true);setTab("classes");}}><small>Vagas disponíveis</small><strong>{totalVacancies}</strong><span>{occupancy}% de ocupação média</span></button>
            </div>
          </section>
          <KidsReplacementOperationSummary data={data} onOpenStudent={openStudent} />
          <section className={styles.capacityPanel}>
            <div className={styles.panelHead}>
              <div>
                <h2>Vagas e capacidade</h2>
                <p>Veja rapidamente quais turmas estão lotadas e onde ainda há espaço.</p>
              </div>
              <button onClick={() => {setVacanciesOnly(false);setTab("classes");}}>Abrir todas as turmas</button>
            </div>
            <div className={styles.capacitySummary}>
              <span><b>{activeClassesByCapacity.filter(item=>item.rate>=100).length}</b> lotadas</span>
              <span><b>{activeClassesByCapacity.filter(item=>item.rate>=80&&item.rate<100).length}</b> quase lotadas</span>
              <span><b>{activeClassesByCapacity.filter(item=>item.rate>=50&&item.rate<80).length}</b> equilibradas</span>
              <span><b>{activeClassesByCapacity.filter(item=>item.rate<50).length}</b> baixa ocupação</span>
            </div>
            <div className={styles.capacityList}>
              {activeClassesByCapacity.map(item=><button key={item.id} onClick={()=>openClass(item.id)}>
                <span className={styles.categoryDots}><CategoryDot category={item.category}/></span>
                <span className={styles.capacityMain}><strong>{item.name}</strong><small>{weekdayLabel[item.weekday]} · {item.startTime} · {item.teacher}</small></span>
                <span className={styles.capacityNumbers}><b>{item.enrolled}/{item.classCapacity}</b><small>{item.vacancies} vaga{item.vacancies===1?"":"s"}</small></span>
                <span className={`${styles.capacityStatus} ${item.enrolled>item.classCapacity?styles.capacityFull:item.enrolled===item.classCapacity?styles.capacityNear:styles.capacityOk}`}>{item.status}</span>
                <span className={`${styles.capacityBar} ${item.enrolled>item.classCapacity?styles.capacityOver:item.enrolled===item.classCapacity?styles.capacityLimit:styles.capacityAvailable}`}><i style={{width:`${Math.min(100,item.rate)}%`}}/></span>
              </button>)}
            </div>
          </section>
          <section className="kids-mobile-quick-search">
            <label htmlFor="kids-dashboard-search">Buscar aluno Kids</label>
            <div className="kids-search-input-wrap"><span>⌕</span><input id="kids-dashboard-search" value={dashboardStudentSearch} onChange={event=>setDashboardStudentSearch(event.target.value)} placeholder="Digite o nome da criança..." autoComplete="off"/></div>
            {dashboardSearchResults.length?<div className="kids-search-results">{dashboardSearchResults.map(student=><button key={student.id} onClick={()=>{setDashboardStudentSearch("");openStudent(student.id);}}><strong>{student.name}</strong><small>{student.classIds.length} turma{student.classIds.length===1?"":"s"}</small><span>›</span></button>)}</div>:dashboardStudentSearch.trim()?<div className="kids-search-empty">Nenhuma criança encontrada.</div>:null}
          </section>
          <section className={styles.panel}>
            <div className={styles.panelHead}>
              <div>
                <h2>Aulas de hoje</h2>
                <p>
                  Abra uma aula para registrar presença, objetivo e plano
                  realizado.
                </p>
              </div>
              <button onClick={() => setTab("agenda")}>Abrir agenda</button>
            </div>
            {todayLessons.length ? (
              <div className={styles.lessonList}>
                {todayLessons.map((lesson) => (
                  <LessonRow
                    key={lesson.id}
                    lesson={lesson}
                    group={lessonGroup(lesson)}
                    fifthReplacement={isKidsFifthMonthlyLesson(data,lesson)}
                    onClick={() => openLesson(lesson.id)}
                  />
                ))}
              </div>
            ) : (
              <Empty
                title="Nenhuma aula Kids hoje"
                text="Consulte as próximas aulas na agenda do semestre."
              />
            )}
          </section>
          <section className={styles.grid2}>
            <article className={styles.panel}>
              <h2>Próximas aulas</h2>
              <div className={styles.lessonList}>
                {lessons
                  .filter(
                    (item) => item.date >= today && item.status === "SCHEDULED",
                  )
                  .sort(
                    (a, b) =>
                      a.date.localeCompare(b.date) ||
                      lessonTime(a).localeCompare(lessonTime(b)),
                  )
                  .slice(0, 6)
                  .map((lesson) => (
                    <LessonRow
                      key={lesson.id}
                      lesson={lesson}
                      group={lessonGroup(lesson)}
                      fifthReplacement={isKidsFifthMonthlyLesson(data,lesson)}
                      onClick={() => openLesson(lesson.id)}
                    />
                  ))}
              </div>
            </article>
            <article className={styles.panel}>
              <h2>Todos os alunos</h2>
              <p>Clique na criança para consultar suas turmas e seus dados.</p>
              <div className={styles.kidsRoster}>
                {allKids.map((student) => (
                  <button
                    key={student.id}
                    onClick={() => openStudent(student.id)}
                  >
                    <span className={styles.categoryDots}>
                      {student.categories.map((category) => (
                        <CategoryDot key={category} category={category} />
                      ))}
                    </span>
                    <strong>{student.name}</strong>
                    <small>
                      {student.classIds.length} turma
                      {student.classIds.length === 1 ? "" : "s"}
                    </small>
                    <span>›</span>
                  </button>
                ))}
              </div>
            </article>
          </section>
        </>
      ) : null}

      {tab === "agenda" ? (
        <section className={styles.panel}>
          <div className={styles.panelHead}>
            <div>
              <h2>
                {agendaFilter === "ALL"
                  ? "Agenda do semestre"
                  : agendaFilter === "COMPLETED"
                    ? "Aulas realizadas"
                    : agendaFilter === "CANCELLED"
                      ? "Aulas canceladas"
                      : "Reposições pendentes"}
              </h2>
              <p>
                Aulas, feriados, cancelamentos e reposições em uma única lista.
              </p>
            </div>
            {agendaFilter === "ALL" ? (
              <input
                type="month"
                value={month}
                min="2026-08"
                max="2026-12"
                onChange={(event) => setMonth(event.target.value)}
              />
            ) : (
              <button onClick={() => setAgendaFilter("ALL")}>
                Ver agenda completa
              </button>
            )}
          </div>
          <div className={styles.lessonList}>
            {displayedLessons.length ? (
              displayedLessons.map((lesson) => (
                <LessonRow
                  key={lesson.id}
                  lesson={lesson}
                  group={lessonGroup(lesson)}
                  fifthReplacement={isKidsFifthMonthlyLesson(data,lesson)}
                  onClick={() => openLesson(lesson.id)}
                />
              ))
            ) : (
              <Empty
                title="Nenhuma aula encontrada"
                text={
                  agendaFilter === "ALL"
                    ? "Escolha outro mês do semestre."
                    : "Não há registros nesta categoria."
                }
              />
            )}
          </div>
        </section>
      ) : null}

      {tab === "classes" ? (
        <section className={styles.panel}>
          <div className={styles.panelHead}>
            <div>
              <h2>{vacanciesOnly ? "Turmas com vagas" : "Turmas"}</h2>
              <p>
                {vacanciesOnly
                  ? "Veja rapidamente onde ainda é possível matricular crianças."
                  : "Relação inicial importada da agenda. Confira e edite quando necessário."}
              </p>
            </div>
            {vacanciesOnly ? (
              <button onClick={() => setVacanciesOnly(false)}>Ver todas</button>
            ) : null}
          </div>
          <div className={styles.classGrid}>
            {classes
              .filter(
                (item) =>
                  !vacanciesOnly ||
                  item.students.filter((student) => student.active).length <
                    (item.category === "RED" || item.category === "ORANGE"
                      ? 6
                      : 4),
              )
              .slice()
              .sort(
                (a, b) =>
                  a.weekday - b.weekday ||
                  a.startTime.localeCompare(b.startTime),
              )
              .map((item) => {
                const activeStudents=item.students.filter(student=>student.active).sort((a,b)=>localeCompare(a.name,b.name));
                const enrolled = activeStudents.length;
                const slots =
                  item.category === "RED" || item.category === "ORANGE" ? 6 : 4;
                return (
                  <button
                    className={styles.classCard}
                    key={item.id}
                    onClick={() => openClass(item.id)}
                  >
                    <CategoryDot category={item.category} />
                    <span className={styles.classCardMain}>
                      <strong>{item.name}</strong>
                      <small>
                        {enrolled}/{slots} alunos ·{" "}
                        {Math.max(0, slots - enrolled)} vagas disponíveis
                      </small>
                      <small className={styles.classCardStudents}>
                        {activeStudents.length
                          ? <><span>Alunos:</span> {activeStudents.map(student=>student.name).join(", ")}</>
                          : "Nenhum aluno ativo"}
                      </small>
                    </span>
                    <b>Abrir</b>
                  </button>
                );
              })}
          </div>
        </section>
      ) : null}

      {tab === "students" ? (
        <section className={styles.panel}>
          <div className={styles.panelHead}>
            <div>
              <h2>{showInactiveStudents?"Alunos inativos":"Alunos"}</h2>
              <p>{showInactiveStudents?"Cadastros preservados fora das chamadas atuais.":"Cadastro único das crianças e todas as suas turmas."}</p>
            </div>
            <div style={{display:"flex",gap:8,flexWrap:"wrap",justifyContent:"flex-end"}}>
              {!showInactiveStudents?<button className={styles.primary} onClick={()=>setShowNewStudentForm(true)}>+ Novo aluno</button>:null}
              <button onClick={()=>setShowInactiveStudents(current=>!current)}>{showInactiveStudents?"Ver alunos ativos":`Ver alunos inativos (${inactiveKids.length})`}</button>
            </div>
          </div>
          <div className="kids-students-search">
            <div className="kids-search-input-wrap"><span>⌕</span><input value={studentSearch} onChange={event=>setStudentSearch(event.target.value)} placeholder={showInactiveStudents?"Buscar aluno inativo...":"Buscar criança pelo nome..."} autoComplete="off"/></div>
          </div>
          <div className={styles.kidsRoster}>
            {(showInactiveStudents?filteredInactiveKids:filteredActiveKids).map((student) => (
              <button key={student.id} onClick={() => openStudent(student.id)}>
                <span className={styles.categoryDots}>
                  {student.categories.map((category) => (
                    <CategoryDot key={category} category={category} />
                  ))}
                </span>
                <span className={styles.kidsRosterMain}>
                  <strong>{student.name}</strong>
                  <small>
                    {student.classIds.map(id=>classes.find(group=>group.id===id)?.name).filter(Boolean).join(" · ")}
                  </small>
                </span>
                <small>{student.classIds.length} turma{student.classIds.length === 1 ? "" : "s"}</small>
                <span>›</span>
              </button>
            ))}
          </div>
        </section>
      ) : null}

      {tab === "replacements" ? (
        <section className={styles.panel}>
          <div className={styles.panelHead}>
            <div><h2>Gestão de reposições</h2><p>Crie aulas, administre participantes, faça chamadas e consulte o histórico.</p></div>
            <button className={styles.primary} onClick={()=>setShowReplacementForm(true)}>+ Aula avulsa de reposição</button>
          </div>
          <div className={styles.replacementWorkspace}>
            <label className={styles.replacementSearch}>
              <span>⌕</span>
              <input value={replacementSearch} onChange={event=>setReplacementSearch(event.target.value)} placeholder="Buscar criança, aula ou data..." autoComplete="off"/>
            </label>

            <div className={styles.replacementWorkspaceGrid}>
              <article className={styles.replacementWorkspaceCard}>
                <header><div><small>PRÓXIMAS AULAS</small><h3>Reposições agendadas</h3></div><b>{visibleUpcomingReplacements.length}</b></header>
                <div className={styles.replacementSessionList}>
                  {visibleUpcomingReplacements.length?visibleUpcomingReplacements.map(lesson=>{
                    const roster=replacementRosterIds(lesson);
                    return <button type="button" key={lesson.id} onClick={()=>openLesson(lesson.id)}>
                      <time><strong>{formatDate(lesson.date)}</strong><small>{lesson.replacementStartTime||lessonTime(lesson)}</small></time>
                      <span><strong>{lesson.replacementName||lessonGroup(lesson)?.name||"Aula de reposição"}</strong><small>{roster.length} criança{roster.length===1?"":"s"} inscrita{roster.length===1?"":"s"}</small></span>
                      <b>Abrir turma e chamada</b>
                    </button>;
                  }):<Empty title="Nenhuma reposição agendada" text={replacementSearch?"Nenhuma aula corresponde à busca.":"Crie uma aula avulsa quando precisar."}/>}
                </div>
              </article>

              <article className={styles.replacementWorkspaceCard}>
                <header><div><small>CONTROLE INDIVIDUAL</small><h3>Alunos aguardando reposição</h3></div><b>{waitingReplacementStudents.length}</b></header>
                <div className={styles.replacementStudentList}>
                  {waitingReplacementStudents.length?waitingReplacementStudents.map(student=><button type="button" key={student.id} onClick={()=>openStudent(student.id)}>
                    <span><strong>{student.name}</strong><small>{student.balance.due} cancelada{student.balance.due===1?"":"s"} · {student.balance.replaced} reposta{student.balance.replaced===1?"":"s"}</small></span>
                    <b>{student.saldoARepor}</b><em>a repor</em>
                  </button>):<Empty title="Nenhuma criança aguardando" text={replacementSearch?"Nenhum aluno corresponde à busca.":"Todos os créditos estão compensados."}/>}
                </div>
              </article>

              <article className={styles.replacementWorkspaceCard}>
                <header><div><small>AULAS CONCLUÍDAS</small><h3>Histórico de reposições</h3></div><b>{visibleReplacementHistory.length}</b></header>
                <div className={styles.replacementSessionList}>
                  {visibleReplacementHistory.length?visibleReplacementHistory.map(lesson=>{
                    const roster=replacementRosterIds(lesson);
                    const absent=roster.filter(id=>lesson.attendance?.[id]==="ABSENT").length;
                    const present=Math.max(0,roster.length-absent);
                    const fifth=lesson.kind!=="REPLACEMENT";
                    return <button type="button" key={lesson.id} onClick={()=>openLesson(lesson.id)}>
                      <time><strong>{formatDate(lesson.date)}</strong><small>{lesson.replacementStartTime||lessonTime(lesson)}</small></time>
                      <span><strong>{fifth?`5ª aula do mês · ${lessonGroup(lesson)?.name||"Turma"}`:lesson.replacementName||lessonGroup(lesson)?.name||"Aula de reposição"}</strong><small>{present} presença{present===1?"":"s"} · {absent} falta{absent===1?"":"s"}</small></span>
                      <b>Ver chamada</b>
                    </button>;
                  }):<Empty title="Nenhuma reposição realizada" text={replacementSearch?"Nenhum histórico corresponde à busca.":"As aulas concluídas aparecerão aqui."}/>}
                </div>
              </article>

              <article className={styles.replacementWorkspaceCard}>
                <header><div><small>SALDO ANTECIPADO</small><h3>Créditos antecipados</h3></div><b>{advanceReplacementStudents.length}</b></header>
                <div className={styles.replacementStudentList}>
                  {advanceReplacementStudents.length?advanceReplacementStudents.map(student=><button type="button" key={student.id} onClick={()=>openStudent(student.id)}>
                    <span><strong>{student.name}</strong><small>Reposições feitas além das aulas canceladas</small></span>
                    <b>{student.saldoARepor}</b><em>saldo</em>
                  </button>):<Empty title="Nenhum crédito antecipado" text={replacementSearch?"Nenhum aluno corresponde à busca.":"Não há saldos negativos no momento."}/>}
                </div>
              </article>
            </div>
          </div>
        </section>
      ) : null}

      {tab === "events" ? <KidsEvents events={data.events||[]} onSave={saveEvent} onDelete={deleteEvent}/> : null}

      {tab === "reports" ? (
        <Reports
          data={data}
          kind={reportKind}
          setKind={setReportKind}
          reportId={reportId}
          setReportId={setReportId}
          financeData={financeData}
        />
      ) : null}
      {lessonId ? (
        <LessonEditor
          lesson={lessons.find((item) => item.id === lessonId)!}
          group={lessonGroup(lessons.find((item) => item.id === lessonId)!)!}
          replacements={data.replacements||[]}
          allStudents={allStudentProfiles}
          onClose={() => setLessonId(null)}
          onSave={updateLesson}
        />
      ) : null}
      {showReplacementForm ? <ReplacementLessonForm replacements={data.replacements||[]} students={allStudentProfiles} classes={classes} lessons={lessons} onClose={()=>setShowReplacementForm(false)} onSave={createReplacementLesson}/> : null}
      {showNewStudentForm?<NewStudentForm classes={classes.filter(item=>item.active)} semesterStart={data.semesterStart} onClose={()=>setShowNewStudentForm(false)} onSave={createStudent}/>:null}
      {classId ? (
        <ClassEditor
          group={group(classId)!}
          lessons={lessons}
          semesterStart={data.semesterStart}
          semesterEnd={data.semesterEnd}
          onClose={() => setClassId(null)}
          onSave={updateClass}
          onOpenLesson={(id)=>{setClassId(null);openLesson(id);}}
        />
      ) : null}
      {studentId ? (
        <StudentEditor
          studentId={studentId}
          data={data}
          classes={classes}
          lessons={lessons}
          replacements={data.replacements || []}
          semesterStart={data.semesterStart}
          onClose={() => setStudentId(null)}
          onOpenClass={openClass}
          onSave={updateStudentClasses}
        />
      ) : null}
    </div>
  );
}

function NewStudentForm({classes,semesterStart,onClose,onSave}:{classes:KidsClass[];semesterStart:string;onClose:()=>void;onSave:(input:{name:string;classId:string;startDate:string})=>void}){
  const [name,setName]=useState("");
  const [classId,setClassId]=useState(classes[0]?.id||"");
  const [startDate,setStartDate]=useState(semesterStart);
  return <div className={styles.modalBackdrop}><section className={styles.modal}>
    <div className={styles.modalHead}><div><h2>Novo aluno</h2><p>Cadastre a criança na DS e escolha a turma inicial.</p></div><button onClick={onClose}>×</button></div>
    <div className={styles.formGrid}>
      <label>Nome da criança<input value={name} onChange={event=>setName(event.target.value)} autoFocus placeholder="Nome completo"/></label>
      <label>Turma<select value={classId} onChange={event=>setClassId(event.target.value)}>{classes.map(group=><option key={group.id} value={group.id}>{group.name}</option>)}</select></label>
      <label>Início na turma<input type="date" min={semesterStart} value={startDate} onChange={event=>setStartDate(event.target.value)}/></label>
    </div>
    {!classes.length?<p>Nenhuma turma ativa disponível.</p>:null}
    <div className={styles.modalActions}><button onClick={onClose}>Cancelar</button><button className={styles.primary} disabled={!name.trim()||!classId} onClick={()=>onSave({name,classId,startDate})}>Cadastrar e completar dados</button></div>
  </section></div>;
}

function KidsEvents({events,onSave,onDelete}:{events:KidsEvent[];onSave:(event:KidsEvent)=>void;onDelete:(eventId:string)=>void}){
  const [query,setQuery]=useState("");
  const currentYear=new Intl.DateTimeFormat("en-CA",{timeZone:"America/Sao_Paulo",year:"numeric"}).format(new Date());
  const [year,setYear]=useState(currentYear);
  const [month,setMonth]=useState("ALL");
  const [editingEvent,setEditingEvent]=useState<KidsEvent|null>(null);
  const [showExport,setShowExport]=useState(false);
  const years=[...new Set(events.map(item=>item.year))].sort();
  const normalized=query.trim().toLocaleLowerCase("pt-BR");
  const filtered=events.filter(event=>(year==="ALL"||String(event.year)===year)&&(month==="ALL"||event.startDate.slice(5,7)===month)&&(!normalized||`${event.name} ${event.description||""} ${event.notes||""}`.toLocaleLowerCase("pt-BR").includes(normalized))).sort((a,b)=>{
    const todayKey=new Intl.DateTimeFormat("en-CA",{timeZone:"America/Sao_Paulo",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date());
    const aPast=(a.endDate||a.startDate)<todayKey;const bPast=(b.endDate||b.startDate)<todayKey;
    if(aPast!==bPast)return aPast?1:-1;
    return aPast?b.startDate.localeCompare(a.startDate):a.startDate.localeCompare(b.startDate);
  });
  const visibleYears=[...new Set(filtered.map(item=>item.year))].sort();
  const createEvent=()=>{
    const today=new Intl.DateTimeFormat("en-CA",{timeZone:"America/Sao_Paulo",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date());
    setEditingEvent({id:`event-${crypto.randomUUID()}`,name:"",startDate:today,endDate:today,year:Number(today.slice(0,4)),status:"PROGRAMMED",type:"OTHER",description:"",notes:"",driveUrl:""});
  };
  const duplicateEvent=(event:KidsEvent)=>setEditingEvent({...event,id:`event-${crypto.randomUUID()}`,name:`${event.name} — cópia`});
  return <section className={styles.panel}>
    <div className={styles.panelHead}>
      <div><h2>Eventos DS Tennis</h2><p>Calendário anual, informações e pastas de trabalho no Google Drive.</p></div>
      <div className={styles.eventHeaderActions}><button onClick={()=>setShowExport(true)}>Exportar</button><button className={styles.primary} onClick={createEvent}>+ Novo evento</button></div>
    </div>
    <div className={styles.eventFilters}><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Buscar evento..."/><select value={year} onChange={event=>setYear(event.target.value)}><option value="ALL">Todos os anos</option>{years.map(value=><option key={value} value={value}>{value}</option>)}</select><select value={month} onChange={event=>setMonth(event.target.value)}><option value="ALL">Todos os meses</option>{Array.from({length:12},(_,index)=>{const value=String(index+1).padStart(2,"0");return <option key={value} value={value}>{new Date(2026,index,1).toLocaleDateString("pt-BR",{month:"long"})}</option>;})}</select></div>
    {visibleYears.map(value=><div key={value} className={styles.eventsYear}>
      <h3>{value}</h3>
      <div className={styles.eventsGrid}>{filtered.filter(item=>item.year===value).map(event=><KidsEventCard key={event.id} event={event} onEdit={()=>setEditingEvent(event)} onDuplicate={()=>duplicateEvent(event)} onDelete={()=>{if(confirm(`Excluir o evento "${event.name}"?`))onDelete(event.id);}}/>)}</div>
    </div>)}
    {!filtered.length?<Empty title="Nenhum evento encontrado" text="Altere os filtros ou crie um novo evento."/>:null}
    {editingEvent?<KidsEventEditor event={editingEvent} onClose={()=>setEditingEvent(null)} onSave={event=>{onSave(event);setEditingEvent(null);}}/>:null}
    {showExport?<EventExportModal events={events} defaultYear={year==="ALL"?currentYear:year} onClose={()=>setShowExport(false)}/>:null}
  </section>;
}

function eventStatusLabel(event:KidsEvent){
  const todayKey=new Intl.DateTimeFormat("en-CA",{timeZone:"America/Sao_Paulo",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date());
  const past=(event.endDate||event.startDate)<todayKey;
  const status=event.status||(past?"COMPLETED":"PROGRAMMED");
  return ({PROGRAMMED:"Programado",CONFIRMED:"Confirmado",COMPLETED:"Concluído",CANCELLED:"Cancelado"} as const)[status];
}
function eventExportTitle(period:string,year:string){return period==="MONTH"?"Calendário de eventos · mês":period==="SEMESTER"?"Calendário de eventos · semestre":period==="YEAR"?`Calendário de Eventos ${year}`:period==="CUSTOM"?"Calendário de eventos":"Próximos Eventos DS Tennis";}
function escapeXml(value:string){const map:Record<string,string>={"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&apos;"};return value.replace(/[&<>"']/g,char=>map[char]||char);}
async function logoDataUrl(){
  try{const response=await fetch("/logo-ctds.png");if(!response.ok)return "";const blob=await response.blob();return await new Promise<string>(resolve=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||""));reader.onerror=()=>resolve("");reader.readAsDataURL(blob);});}catch{return "";}
}
function EventExportModal({events,defaultYear,onClose}:{events:KidsEvent[];defaultYear:string;onClose:()=>void}){
  const todayKey=new Intl.DateTimeFormat("en-CA",{timeZone:"America/Sao_Paulo",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date());
  const [period,setPeriod]=useState<"UPCOMING"|"MONTH"|"SEMESTER"|"YEAR"|"CUSTOM">("UPCOMING");
  const [format,setFormat]=useState<"IMAGE"|"PDF"|"LIST">("IMAGE");
  const [confirmedOnly,setConfirmedOnly]=useState(false);
  const [includeDescription,setIncludeDescription]=useState(true);
  const [customStart,setCustomStart]=useState(todayKey);
  const [customEnd,setCustomEnd]=useState(`${defaultYear}-12-31`);
  const monthKey=todayKey.slice(0,7);
  const currentMonth=Number(todayKey.slice(5,7));
  const semesterStart=`${defaultYear}-${currentMonth<=6?"01":"07"}-01`;
  const semesterEnd=`${defaultYear}-${currentMonth<=6?"06-30":"12-31"}`;
