ange={e=>setProfile(current=>({...current,studentSummaryMessage:e.target.value}))}/></label><button className="primary" disabled={savingProfile} onClick={()=>void saveProfile()}>{savingProfile?"Salvando...":"Salvar mensagem do resumo"}</button></article><article className="panel settings-health-panel"><div className="panel-head"><div><h2>Central de saúde do DMP</h2><p className="muted">Visão rápida dos serviços essenciais.</p></div></div><div className="settings-health-list">{healthItems.map(([label,status,detail])=><div key={String(label)}><span className={`health-dot ${String(status||"").includes("Conectado")||String(status)==="Online"||String(status).startsWith("Último")||String(status)==="Pronto"?"ok":"warn"}`}/><div><strong>{label}</strong><small>{status||"Verificando..."}{detail?` · ${detail}`:""}</small></div></div>)}</div></article></section></>;
