        data.classes.flatMap(group=>group.students||[]).forEach(student=>{
          if(student?.id&&!unique.has(student.id))unique.set(student.id,student);
        });
        setKidsSearchStudents([...unique.values()]);
      })
      .catch(()=>{if(!cancelled)setKidsSearchStudents([]);});
